commands.es:
CREATE TABLE notas (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  cuerpo text NOT NULL
);

commands.en:
CREATE TABLE notes (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  body text NOT NULL
);

commands.es:
BEGIN;
UPDATE notas SET cuerpo = 'nuevo' WHERE id = 1;
ROLLBACK;

commands.en:
BEGIN;
UPDATE notes SET body = 'new' WHERE id = 1;
ROLLBACK;

commands.es:
SELECT p.id, c.email
FROM pedidos p
JOIN clientes c ON c.id = p.cliente_id;

commands.en:
SELECT o.id, c.email
FROM orders o
JOIN customers c ON c.id = o.customer_id;

